package io.mdexporter;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/** Version and commit of the running build, generated by the git-commit-id Maven plugin. */
public final class BuildInfo {

    private static final Properties PROPS = load();

    private BuildInfo() {
    }

    private static Properties load() {
        Properties props = new Properties();
        try (InputStream in = BuildInfo.class.getResourceAsStream("/io/mdexporter/build-info.properties")) {
            if (in != null) {
                props.load(in);
            }
        } catch (IOException ignored) {
            // unknown build
        }
        return props;
    }

    /** Project version, e.g. {@code 1.1.0-SNAPSHOT}. */
    public static String version() {
        String version = PROPS.getProperty("git.build.version");
        if (version == null) {
            version = BuildInfo.class.getPackage().getImplementationVersion();
        }
        return version == null ? "development" : version;
    }

    /** Abbreviated commit id, with {@code -dirty} when built from modified sources; {@code null} if unknown. */
    public static String commit() {
        String id = PROPS.getProperty("git.commit.id.abbrev");
        if (id == null || id.isBlank()) {
            return null;
        }
        return Boolean.parseBoolean(PROPS.getProperty("git.dirty")) ? id + "-dirty" : id;
    }

    public static String commitFull() {
        return PROPS.getProperty("git.commit.id.full");
    }

    public static String commitTime() {
        return PROPS.getProperty("git.commit.time");
    }

    public static String buildTime() {
        return PROPS.getProperty("git.build.time");
    }

    public static String branch() {
        return PROPS.getProperty("git.branch");
    }

    /** One line summary: {@code 1.1.0 (commit 9e47fe5)}. */
    public static String summary() {
        String commit = commit();
        return version() + (commit == null ? "" : " (commit " + commit + ")");
    }
}
